import React from 'react';
import { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar(){
    const [isOpen, setIsOpen] = useState(false);
    return(
        <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] p-4 flex flex-wrap items-center justify-between">
        <img src="logo.png" alt="Logo" className="h-12" />

        {/* Mobile menu toggle */}
        <div className="md:hidden ml-auto">
            <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="text-2xl font-bold"
            >
            ☰
            </button>
        </div>

        {/* Nav + Button Container */}
        <div
            className={`w-full md:w-auto md:flex md:items-center md:space-x-6 ${
            isMenuOpen ? "block" : "hidden"
            }`}
        >
            {/* Nav Links */}
            <nav className="flex flex-col items-center gap-4 md:flex-row md:gap-6 text-[clamp(0.9rem,2vw,1.1rem)] font-semibold text-[#292929] mx-auto md:mx-0">
            <a href="#" className="text-[#f48f0f]">Home</a>
            <a href="#">About</a>
            <a href="#">Gallery</a>
            <a href="#">Education</a>
            </nav>

            {/* Button - right aligned on desktop, centered on mobile */}
            <div className="mt-4 md:mt-0 md:ml-auto">
            <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
                Become a member
            </button>
            </div>
        </div>
        </header>

    );
}

export default Navbar;
